<div class="order-detail-grid">
    <section class="form-card"><h2>Customer</h2><p><strong><?= h($order['customer_name']) ?></strong></p><p><?= h($order['customer_phone']) ?> · <?= h($order['customer_email']) ?></p></section>
    <section class="form-card"><h2>Delivery Address</h2><p><?= h($order['delivery_address']) ?></p><p><?= h($order['area']) ?>, <?= h($order['city']) ?></p></section>
    <section class="form-card"><h2>Status</h2><form method="post" action="<?= url('admin/order') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= h($order['id']) ?>"><select name="status"><?php foreach (['pending','confirmed','processing','out_for_delivery','delivered','cancelled'] as $s): ?><option value="<?= $s ?>" <?= $order['status']===$s?'selected':'' ?>><?= h(ucwords(str_replace('_',' ',$s))) ?></option><?php endforeach; ?></select><button class="btn btn-primary btn-sm">Update</button></form></section>
</div>
<section class="table-card"><div class="card-head"><h2>Items</h2><a class="btn btn-outline btn-sm" href="<?= url('admin/invoice', ['id'=>$order['id']]) ?>">Print Invoice</a></div><table class="data-table"><thead><tr><th>Product</th><th>Variant</th><th>Unit</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php foreach ($order['items'] as $item): ?><tr><td><?= h($item['product_name']) ?></td><td><?= h($item['variant_name']) ?></td><td class="num"><?= money($item['unit_price']) ?></td><td class="num"><?= h($item['quantity']) ?></td><td class="num"><?= money($item['line_total']) ?></td></tr><?php endforeach; ?></tbody></table></section>
<section class="summary-card admin-summary"><p><span>Subtotal</span><strong><?= money($order['subtotal']) ?></strong></p><p><span>Delivery</span><strong><?= money($order['delivery_charge']) ?></strong></p><p><span>Discount</span><strong>-<?= money($order['discount_amount']) ?></strong></p><p class="total"><span>Total</span><strong><?= money($order['total_amount']) ?></strong></p></section>
